#include "autoconf.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include "gdbm.h"
#include "progname.h"

void
print_key (FILE *fp, datum key, int delim)
{
  size_t i;

  for (i = 0; i < key.dsize && key.dptr[i]; i++)
    {
      if (key.dptr[i] == delim || key.dptr[i] == '\\')
        fputc ('\\', fp);
      fputc (key.dptr[i], fp);
    }
}

int
main (int argc, char **argv)
{
  const char *progname = canonical_progname (argv[0]);
  const char *dbname;
  datum key;
  datum data;
  int flags = 0;
  GDBM_FILE dbf;
  int data_z = 0;
  int delim = 0;
  int rc = 0;

  while (--argc)
    {
      char *arg = *++argv;

      if (strcmp (arg, "-h") == 0)
        {
          printf ("usage: %s [-nolock] [-nommap] [-null] [-delim=CHR] DBFILE KEY [KEY...]\n",
                  progname);
          exit (0);
        }
      else if (strcmp (arg, "-nolock") == 0)
        flags |= GDBM_NOLOCK;
      else if (strcmp (arg, "-nommap") == 0)
        flags |= GDBM_NOMMAP;
      else if (strcmp (arg, "-null") == 0)
        data_z = 1;
      else if (strncmp (arg, "-delim=", 7) == 0)
        delim = arg[7];
      else if (strcmp (arg, "--") == 0)
        {
          --argc;
          ++argv;
          break;
        }
      else if (arg[0] == '-')
        {
          fprintf (stderr, "%s: unknown option %s\n", progname, arg);
          exit (1);
        }
      else
        break;
    }

  if (argc < 2)
    {
      fprintf (stderr, "%s: wrong arguments\n", progname);
      exit (1);
    }
  dbname = *argv;

  dbf = gdbm_open (dbname, 0, GDBM_READER|flags, 00664, NULL);
  if (!dbf)
    {
      fprintf (stderr, "gdbm_open failed: %s\n", gdbm_strerror (gdbm_errno));
      exit (1);
    }

  while (--argc)
    {
      char *arg = *++argv;

      key.dptr = arg;
      key.dsize = strlen (arg) + !!data_z;

      data = gdbm_fetch (dbf, key);
      if (data.dptr == NULL)
        {
          rc = 2;
          if (gdbm_errno == GDBM_ITEM_NOT_FOUND)
            {
              fprintf (stderr, "%s: ", progname);
              print_key (stderr, key, delim);
              fprintf (stderr, ": not found\n");
            }
          else
            {
              fprintf (stderr, "%s: error: %s\n", progname,
                       gdbm_strerror (gdbm_errno));
            }
          continue;
        }
      if (delim)
        {
          print_key (stdout, key, delim);
          fputc (delim, stdout);
        }

      fwrite (data.dptr, data.dsize - !!data_z, 1, stdout);
      free (data.dptr);

      fputc ('\n', stdout);
    }

  if (gdbm_close (dbf))
    {
      fprintf (stderr, "gdbm_close: %s; %s\n", gdbm_strerror (gdbm_errno),
               strerror (errno));
      rc = 3;
    }
  exit (rc);
}
